'use strict';

var metadataHelpers = require('@toruslabs/metadata-helpers');

const ed25519 = metadataHelpers.getEd25519();
function getED25519Key(privateKey) {
  const privKey = typeof privateKey === "string" ? metadataHelpers.hexToBytes(privateKey) : privateKey;
  const pk = ed25519.getPublicKey(privKey);
  const sk = new Uint8Array(64);
  sk.set(privKey, 0);
  sk.set(pk, 32);
  return {
    sk,
    pk
  };
}

exports.getED25519Key = getED25519Key;
